-- 20261004k — Conciliação caso a caso, rodada 3: cadastro + acesso×dinheiro (30/09/2026)
-- Fonte: conciliação por aluno (Hotmart/fin, Respondi, compradores, vínculo declarado). Pedido do João:
-- "corrige tudo ai ate 100" + "dado muito certo pode colocar; se tiver dúvida coloca, mas coloca uma observação".
-- Regras: só alunos ativos; update só se o valor atual não mudou; valor anterior em cruzamentos_correcoes;
-- sócio: desfaz vínculos (fase 1) antes de criar (fase 2) por causa de trg_thb_alunos_trava_vinculo_socio.
-- Fora desta rodada (decisão do João): revogar sócios de titular vencido (classe G), dúvida que tira acesso
-- ou mexe em dinheiro, turma divergente (não vazia), criar ficha de comprador sem ficha.
-- Nomes em socio_de_nome redigidos nesta cópia (repo público); a versão aplicada comparava o valor literal.
-- Documento e CEP literais não entram aqui (repo público): aplicados à parte, com a mesma auditoria.
-- texto da observação e checagem por classe (regra = conc_<classe>:<certo|a_confirmar>)
create temp table _m (cl text, txt text, chk text) on commit drop;
create temp table _c0 (aluno_id uuid, campo text, atual text, novo text, fase int, regra text) on commit drop;
create temp table _c on commit drop as
select c.*, m.txt || case when c.regra like '%:a_confirmar' then ' (a confirmar)' else '' end obs, m.chk
  from _c0 c join _m m on m.cl = split_part(split_part(c.regra, ':', 1), '_', 2);
do $$ begin if (select count(*) from _c) <> (select count(*) from _c0) then raise exception 'classe sem texto'; end if; end $$;
create temp table _ot (i int, obs text) on commit drop;
create temp table _o0 (aluno_id uuid, chk text, i int) on commit drop;
create temp table _o on commit drop as select o.aluno_id, o.chk, t.obs from _o0 o join _ot t using (i);
create temp table _t (aluno_id uuid, codigo text) on commit drop;

do $$
declare n int := 0; k int; m int; t int; e int; r text := '';
begin
  select a.id, c.campo, a.socio_de_aluno_id::text, c.novo, c.regra from public.thb_alunos a join _c c on a.id = c.aluno_id where c.campo = 'socio_de_aluno_id' and c.fase = 1 and a.cancelado_em is null and a.socio_de_aluno_id is not distinct from c.atual::uuid;
  update public.thb_alunos a set socio_de_aluno_id = c.novo::uuid from _c c where a.id = c.aluno_id and c.campo = 'socio_de_aluno_id' and c.fase = 1 and a.cancelado_em is null and a.socio_de_aluno_id is not distinct from c.atual::uuid;
  get diagnostics k = row_count; n := n + k; r := r || ' socio_de_aluno_id.1=' || k;
  select a.id, c.campo, a.acessos_revogados_em::text, c.novo, c.regra from public.thb_alunos a join _c c on a.id = c.aluno_id where c.campo = 'acessos_revogados_em' and c.fase = 2 and a.cancelado_em is null and true;
  update public.thb_alunos a set acessos_revogados_em = c.novo::timestamptz from _c c where a.id = c.aluno_id and c.campo = 'acessos_revogados_em' and c.fase = 2 and a.cancelado_em is null and true;
  get diagnostics k = row_count; n := n + k; r := r || ' acessos_revogados_em.2=' || k;
  select a.id, c.campo, a.acessos_revogados_por::text, c.novo, c.regra from public.thb_alunos a join _c c on a.id = c.aluno_id where c.campo = 'acessos_revogados_por' and c.fase = 2 and a.cancelado_em is null and a.acessos_revogados_por is not distinct from c.atual::text;
  update public.thb_alunos a set acessos_revogados_por = c.novo::text from _c c where a.id = c.aluno_id and c.campo = 'acessos_revogados_por' and c.fase = 2 and a.cancelado_em is null and a.acessos_revogados_por is not distinct from c.atual::text;
  get diagnostics k = row_count; n := n + k; r := r || ' acessos_revogados_por.2=' || k;
  select a.id, c.campo, a.eh_socio::text, c.novo, c.regra from public.thb_alunos a join _c c on a.id = c.aluno_id where c.campo = 'eh_socio' and c.fase = 2 and a.cancelado_em is null and a.eh_socio is not distinct from c.atual::boolean;
  update public.thb_alunos a set eh_socio = c.novo::boolean from _c c where a.id = c.aluno_id and c.campo = 'eh_socio' and c.fase = 2 and a.cancelado_em is null and a.eh_socio is not distinct from c.atual::boolean;
  get diagnostics k = row_count; n := n + k; r := r || ' eh_socio.2=' || k;
  select a.id, c.campo, a.estado::text, c.novo, c.regra from public.thb_alunos a join _c c on a.id = c.aluno_id where c.campo = 'estado' and c.fase = 2 and a.cancelado_em is null and a.estado is not distinct from c.atual::char(2);
  update public.thb_alunos a set estado = c.novo::char(2) from _c c where a.id = c.aluno_id and c.campo = 'estado' and c.fase = 2 and a.cancelado_em is null and a.estado is not distinct from c.atual::char(2);
  get diagnostics k = row_count; n := n + k; r := r || ' estado.2=' || k;
  select a.id, c.campo, a.saldo_devedor::text, c.novo, c.regra from public.thb_alunos a join _c c on a.id = c.aluno_id where c.campo = 'saldo_devedor' and c.fase = 2 and a.cancelado_em is null and a.saldo_devedor is not distinct from c.atual::numeric;
  update public.thb_alunos a set saldo_devedor = c.novo::numeric from _c c where a.id = c.aluno_id and c.campo = 'saldo_devedor' and c.fase = 2 and a.cancelado_em is null and a.saldo_devedor is not distinct from c.atual::numeric;
  get diagnostics k = row_count; n := n + k; r := r || ' saldo_devedor.2=' || k;
  select a.id, c.campo, a.situacao_acesso::text, c.novo, c.regra from public.thb_alunos a join _c c on a.id = c.aluno_id where c.campo = 'situacao_acesso' and c.fase = 2 and a.cancelado_em is null and a.situacao_acesso is not distinct from c.atual::text;
  update public.thb_alunos a set situacao_acesso = c.novo::text from _c c where a.id = c.aluno_id and c.campo = 'situacao_acesso' and c.fase = 2 and a.cancelado_em is null and a.situacao_acesso is not distinct from c.atual::text;
  get diagnostics k = row_count; n := n + k; r := r || ' situacao_acesso.2=' || k;
  select a.id, c.campo, a.situacao_financeira::text, c.novo, c.regra from public.thb_alunos a join _c c on a.id = c.aluno_id where c.campo = 'situacao_financeira' and c.fase = 2 and a.cancelado_em is null and a.situacao_financeira is not distinct from c.atual::text;
  update public.thb_alunos a set situacao_financeira = c.novo::text from _c c where a.id = c.aluno_id and c.campo = 'situacao_financeira' and c.fase = 2 and a.cancelado_em is null and a.situacao_financeira is not distinct from c.atual::text;
  get diagnostics k = row_count; n := n + k; r := r || ' situacao_financeira.2=' || k;
  select a.id, c.campo, a.socio_de_aluno_id::text, c.novo, c.regra from public.thb_alunos a join _c c on a.id = c.aluno_id where c.campo = 'socio_de_aluno_id' and c.fase = 2 and a.cancelado_em is null and a.socio_de_aluno_id is not distinct from c.atual::uuid;
  update public.thb_alunos a set socio_de_aluno_id = c.novo::uuid from _c c where a.id = c.aluno_id and c.campo = 'socio_de_aluno_id' and c.fase = 2 and a.cancelado_em is null and a.socio_de_aluno_id is not distinct from c.atual::uuid;
  get diagnostics k = row_count; n := n + k; r := r || ' socio_de_aluno_id.2=' || k;
  select a.id, c.campo, a.socio_de_nome::text, c.novo, c.regra from public.thb_alunos a join _c c on a.id = c.aluno_id where c.campo = 'socio_de_nome' and c.fase = 2 and a.cancelado_em is null and a.socio_de_nome is not distinct from c.atual::text;
  update public.thb_alunos a set socio_de_nome = c.novo::text from _c c where a.id = c.aluno_id and c.campo = 'socio_de_nome' and c.fase = 2 and a.cancelado_em is null and a.socio_de_nome is not distinct from c.atual::text;
  get diagnostics k = row_count; n := n + k; r := r || ' socio_de_nome.2=' || k;
  select a.id, c.campo, a.status_acesso::text, c.novo, c.regra from public.thb_alunos a join _c c on a.id = c.aluno_id where c.campo = 'status_acesso' and c.fase = 2 and a.cancelado_em is null and a.status_acesso is not distinct from c.atual::text;
  update public.thb_alunos a set status_acesso = c.novo::text from _c c where a.id = c.aluno_id and c.campo = 'status_acesso' and c.fase = 2 and a.cancelado_em is null and a.status_acesso is not distinct from c.atual::text;
  get diagnostics k = row_count; n := n + k; r := r || ' status_acesso.2=' || k;
  select a.id, c.campo, a.status_acesso_central::text, c.novo, c.regra from public.thb_alunos a join _c c on a.id = c.aluno_id where c.campo = 'status_acesso_central' and c.fase = 2 and a.cancelado_em is null and a.status_acesso_central is not distinct from c.atual::text;
  update public.thb_alunos a set status_acesso_central = c.novo::text from _c c where a.id = c.aluno_id and c.campo = 'status_acesso_central' and c.fase = 2 and a.cancelado_em is null and a.status_acesso_central is not distinct from c.atual::text;
  get diagnostics k = row_count; n := n + k; r := r || ' status_acesso_central.2=' || k;
  select a.id, c.campo, a.status_pagamento::text, c.novo, c.regra from public.thb_alunos a join _c c on a.id = c.aluno_id where c.campo = 'status_pagamento' and c.fase = 2 and a.cancelado_em is null and a.status_pagamento is not distinct from c.atual::text;
  update public.thb_alunos a set status_pagamento = c.novo::text from _c c where a.id = c.aluno_id and c.campo = 'status_pagamento' and c.fase = 2 and a.cancelado_em is null and a.status_pagamento is not distinct from c.atual::text;
  get diagnostics k = row_count; n := n + k; r := r || ' status_pagamento.2=' || k;
  select a.id, c.campo, a.valor_pago::text, c.novo, c.regra from public.thb_alunos a join _c c on a.id = c.aluno_id where c.campo = 'valor_pago' and c.fase = 2 and a.cancelado_em is null and a.valor_pago is not distinct from c.atual::numeric;
  update public.thb_alunos a set valor_pago = c.novo::numeric from _c c where a.id = c.aluno_id and c.campo = 'valor_pago' and c.fase = 2 and a.cancelado_em is null and a.valor_pago is not distinct from c.atual::numeric;
