     where a.id = x.id and a.cancelado_em is null and a.telefone_e164 is null
       and ((length(x.d) = 13 and x.d like '55%') or length(x.d) = 11)
    returning a.id, a.telefone_e164)
  select id, 'telefone_e164', null, telefone_e164, 'conc_10:certo' from u;
  get diagnostics t = row_count;
  -- turma vazia: turma da janela de venda da 1ª compra (a confirmar)
  select a.id, 'turma_id', null, tu.id::text, 'conc_11:a_confirmar'
    from _t x join public.thb_alunos a on a.id = x.aluno_id join public.thb_turmas tu on tu.codigo = x.codigo and tu.tipo = 'thb'
   where a.cancelado_em is null and a.turma_id is null and a.turma_aurum_id is null;
  update public.thb_alunos a set turma_id = tu.id,
         obs_central = concat_ws(' | ', nullif(a.obs_central, ''), '[2026-09-30] [conc:turma] ' || 'turma ' || x.codigo || ' pela janela de venda da 1ª compra do programa (a confirmar)')
    from _t x join public.thb_turmas tu on tu.codigo = x.codigo and tu.tipo = 'thb'
   where a.id = x.aluno_id and a.cancelado_em is null and a.turma_id is null and a.turma_aurum_id is null;
  get diagnostics e = row_count;
  -- observação de cada correção aplicada (uma por aluno e checagem) e de cada dúvida não aplicada
  update public.thb_alunos a set obs_central = concat_ws(' | ', nullif(a.obs_central, ''), o.txt)
    from (select aluno_id, string_agg(distinct '[2026-09-30] [conc:' || chk || '] ' || obs, ' | ') txt
            from (select aluno_id, chk, obs from _c union all select aluno_id, chk, obs from _o) u group by aluno_id) o
   where a.id = o.aluno_id and a.cancelado_em is null;
  get diagnostics m = row_count;
  raise notice 'campos aplicados: %, telefones: %, turmas: %, fichas com observação: % |%', n, t, e, m, r;
  if n < 251 or t < 193 or e < 54 then
    raise exception 'contagem abaixo do esperado (279 campos, 215 telefones, 60 turmas): %, %, %', n, t, e;
  end if;
end $$;
